/** Manual versioned cloud/local-provider backup; destructive restore stays in BackupActivity. */
public final class CloudBackupActivity extends Activity {
    static final int TREE=733;
    interface Picker {void choose(CloudBackupActivity activity);}
    static Picker picker=activity->activity.startActivityForResult(new Intent(Intent.ACTION_OPEN_DOCUMENT_TREE).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION|Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION|Intent.FLAG_GRANT_PREFIX_URI_PERMISSION),TREE);
    interface Destinations {void choose(Context context,Uri tree,int flags)throws Exception;void disconnect(Context context);}
    static Destinations destinations=new Destinations(){public void choose(Context c,Uri tree,int flags)throws Exception{CloudBackupProvider.choose(c,tree,flags);}public void disconnect(Context c){CloudBackupProvider.disconnect(c);}};
    /** Accepted folder changes survive rotation without retaining an Activity or its views. */
    private static final class FolderChange {
        static final class State {final boolean busy;final String message;State(boolean busy,String message){this.busy=busy;this.message=message;}}
        interface Operation {void run()throws Exception;}
        final Context app;final ExecutorService worker=Executors.newSingleThreadExecutor(r->new Thread(r,"cloud-backup-folder"));volatile State state=new State(false,"");
        FolderChange(Context context){app=context.getApplicationContext();}
        void choose(Destinations owner,Uri tree,int flags){start("Checking folder access…","Destination remembered. Automatic backup is a separate opt-in below.","Destination could not be remembered. Choose a folder with persistent read/write access.",()->owner.choose(app,tree,flags));}
        void disconnect(Destinations owner){start("Disconnecting destination…","Destination disconnected. Files were kept.","Destination could not be disconnected. Retry.",()->owner.disconnect(app));}
        private void start(String working,String complete,String failure,Operation operation){if(state.busy)return;state=new State(true,working);try{worker.execute(()->{String message=complete;try{operation.run();}catch(Exception unavailable){message=failure;}state=new State(false,message);});}catch(RuntimeException unavailable){state=new State(false,failure);}}
        void close(){worker.shutdown();}
        boolean await(long timeout)throws Exception{if(worker.isShutdown())return worker.awaitTermination(timeout,TimeUnit.MILLISECONDS);worker.submit(()->{}).get(timeout,TimeUnit.MILLISECONDS);return true;}
    }
    private final Handler main=new Handler(Looper.getMainLooper());private final ExecutorService local=Executors.newSingleThreadExecutor(r->new Thread(r,"cloud-backup-settings"));private CloudBackupJob job;private CloudBackupJob.State drawn;private AutoCloudBackups.State autoDrawn;private FolderChange folder;private FolderChange.State folderDrawn;private Records.Factory records;private boolean resumed,selecting;private long generation;private String message="";
    private final Runnable observe=new Runnable(){public void run(){if(!resumed)return;if(drawn!=job.state()||autoDrawn!=AutoCloudBackups.state||folderDrawn!=folder.state)render();main.postDelayed(this,150);}};
    @Override public void onCreate(Bundle saved){super.onCreate(saved);RecordUi.review(this);Object retained=getLastNonConfigurationInstance();folder=retained instanceof FolderChange?(FolderChange)retained:new FolderChange(getApplicationContext());records=Records.factory;job=CloudBackupJobs.get(this,records);if(saved!=null)selecting=saved.getBoolean("selecting");render();}
    @Override public Object onRetainNonConfigurationInstance(){return folder;}
    private void render(){drawn=job.state();autoDrawn=AutoCloudBackups.state;FolderChange.State change=folder.state;if(folderDrawn!=change){folderDrawn=change;if(!change.message.isEmpty())message=change.message;}long ticket=++generation;android.content.SharedPreferences prefs=CloudBackupSettings.factory.preferences(this);CloudBackupSettings.Destination destination=CloudBackupSettings.destination(prefs);LinearLayout body=Design.page(this,false,null,n->{});RecordUi.label(this,body);Design.header(body,"Cloud backup",this::finish);Design.text(body,"Your storage provider",20,600,Design.INK);Design.space(body,8);Design.text(body,"Choose a folder in a cloud storage app or on this phone.",13,400,Design.MUTED);PlanActivity.detail(body,"cloud","Destination",destination.label,destination.tree.isEmpty()?"Not selected":"Remembered",null);Design.line(body);boolean busy=drawn.busy()||change.busy||selecting;if(!drawn.message.isEmpty()){Design.space(body,10);Design.text(body,drawn.message,14,500,Design.BROWN);}if(!message.isEmpty()){Design.space(body,8);Design.text(body,message,13,500,Design.BROWN);}if(prefs.getBoolean("in_progress",false)&&!drawn.busy())Design.text(body,"The previous operation was interrupted. A partial version may remain; review its status below.",12,400,Design.MUTED);Design.space(body,12);Design.text(body,"Version history",18,600,Design.INK);Design.text(body,"Last 20 versions from this installation. Older files stay in your folder.",12,400,Design.MUTED);LinearLayout history=Design.col(this);body.addView(history);automatic(body,destination,busy);Design.space(body,12);PlanActivity.detail(body,"wave","Audio folder backup","Optional manual ZIP versions · complete private recordings",null,()->startActivity(RecordUi.intent(this,CloudAudioActivity.class)));Design.space(body,14);Design.text(body,"JSON includes alarms, sleep records, notes and sound labels. Audio, app settings and goal commitments are excluded. Your storage app controls account access and remote upload.",12,400,Design.MUTED);
        LinearLayout footer=RecordUi.footer(body);if(drawn.busy()){Design.button(footer,"Cancel backup",false,()->{job.cancel();render();});}else{Design.button(footer,"Save a new backup",true,()->{message="";job.save();render();}).setEnabled(!busy&&!autoDrawn.busy&&!destination.tree.isEmpty());Design.button(footer,destination.tree.isEmpty()?"Choose destination":"Change destination",false,this::choose).setEnabled(!busy);if(!destination.tree.isEmpty())Design.button(footer,"Disconnect destination",false,this::disconnect).setEnabled(!busy);}if(selecting)Design.button(footer,"Cancel folder selection",false,()->{selecting=false;message="No destination changed.";render();});
        local.execute(()->{List<CloudBackupSettings.Entry> entries;String issue="";try{entries=CloudBackupSettings.history(prefs);}catch(Exception e){entries=List.of();issue="Local version history is unavailable. Existing files have not been deleted.";}List<CloudBackupSettings.Entry> loaded=entries;String error=issue;main.post(()->{if(isDestroyed()||ticket!=generation)return;if(!error.isEmpty())Design.text(history,error,12,400,Design.MUTED);int count=0;for(CloudBackupSettings.Entry entry:loaded){if(!entry.tree.equals(destination.tree))continue;count++;String date=java.time.Instant.ofEpochMilli(entry.time).atZone(java.time.ZoneId.systemDefault()).format(java.time.format.DateTimeFormatter.ofPattern("d MMM · HH:mm"));PlanActivity.detail(history,"file",date,entry.verified?(entry.size/1024)+" KiB · provider read-back verified":"Unverified or partial version",entry.verified?"Review":null,entry.verified&&!busy?()->review(entry):null);Design.line(history);}if(count==0)Design.text(history,"No saved versions in this destination yet.",13,400,Design.MUTED);});});
    }
    private void automatic(LinearLayout body,CloudBackupSettings.Destination destination,boolean busy){
        Design.space(body,14);LinearLayout row=Design.row(this);LinearLayout text=Design.col(this);Design.text(text,"After a tracked night",17,600,Design.INK);Design.text(text,"Metadata only · off by default",12,400,Design.MUTED);row.addView(text,new LinearLayout.LayoutParams(0,-2,1));Switch option=new Switch(this);option.setContentDescription("Automatic metadata backup");Design.styleSwitch(this,option,Design.BROWN,0xffbcb5b0);option.setChecked(autoDrawn.enabled);option.setEnabled(!busy&&(!autoDrawn.busy||autoDrawn.enabled)&&(!destination.tree.isEmpty()||autoDrawn.enabled));option.setOnCheckedChangeListener((v,on)->{AutoCloudBackups.configure(this,on);render();});row.addView(option,new LinearLayout.LayoutParams(Design.dp(this,58),Design.dp(this,64)));body.addView(row);Design.text(body,autoDrawn.message,13,500,Design.BROWN);if(autoDrawn.pending>0)Design.text(body,autoDrawn.pending+" pending · Android may defer while battery is low",12,400,Design.MUTED);Design.text(body,"Creates a verified JSON version after a successfully saved tracked night. Up to 8 MiB; no audio files. Existing history is not uploaded when you enable this.",12,400,Design.MUTED);if(autoDrawn.enabled&&(autoDrawn.pending>0||autoDrawn.attention>0)){Design.button(body,"Retry automatic backup",false,()->{if(autoDrawn.attention>0)confirmAutoRetry();else AutoCloudBackups.retry(this);}).setEnabled(!autoDrawn.busy&&!busy);}Design.line(body);
    }
    private void confirmAutoRetry(){Dialog dialog=new Dialog(this);dialog.requestWindowFeature(android.view.Window.FEATURE_NO_TITLE);LinearLayout root=Design.col(this);Design.pad(root,22,22);root.setBackground(Design.shape(this,Design.CREAM,24));Design.text(root,"Retry automatic backup?",22,600,Design.INK);Design.space(root,16);Design.text(root,"A complete or partial version may already be in the folder. Retrying creates a new file; existing files are kept.",14,400,Design.MUTED);Design.button(root,"Retry",true,()->{dialog.dismiss();AutoCloudBackups.retry(this);});Design.button(root,"Cancel",false,dialog::dismiss);dialog.setContentView(root);dialog.show();dialog.getWindow().setBackgroundDrawableResource(android.R.color.transparent);dialog.getWindow().setLayout(Math.min(Design.dp(this,380),getResources().getDisplayMetrics().widthPixels-Design.dp(this,32)),-2);}
    private void choose(){if(job.state().busy()||folder.state.busy||selecting)return;selecting=true;message="Choose a folder in Android.";render();try{picker.choose(this);}catch(RuntimeException e){selecting=false;message="Folder chooser unavailable. Install a document provider or retry.";render();}}
    @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request!=TREE||!selecting||isFinishing()||isDestroyed())return;selecting=false;if(result!=RESULT_OK||data==null||data.getData()==null){message="No destination changed.";render();return;}folder.choose(destinations,data.getData(),data.getFlags());render();}
    private void disconnect(){if(job.state().busy()||folder.state.busy)return;new AlertDialog.Builder(this).setTitle("Disconnect destination?").setMessage("Stops remembering this folder. Existing backup files are kept.").setNegativeButton("Cancel",null).setPositiveButton("Disconnect",(d,w)->{if(isFinishing()||isDestroyed())return;folder.disconnect(destinations);render();}).show();}
    private void review(CloudBackupSettings.Entry entry){if(job.state().busy()||folder.state.busy||selecting)return;BackupJob existing=BackupJobs.get(this,records);if(existing.state().busy()){message="Finish the current document operation first.";render();return;}startActivity(RecordUi.intent(this,BackupActivity.class).putExtra("document",entry.uri).putExtra("kind",BackupJob.Kind.IMPORT.name()).putExtra("expectedSha",entry.sha));}
    @Override protected void onResume(){super.onResume();resumed=true;AutoCloudBackups.inspect(this);render();main.post(observe);}
    @Override protected void onPause(){resumed=false;main.removeCallbacks(observe);super.onPause();}
    @Override public void onSaveInstanceState(Bundle state){super.onSaveInstanceState(state);state.putBoolean("selecting",selecting);}
    @Override public void onWindowFocusChanged(boolean focused){super.onWindowFocusChanged(focused);if(focused)RecordUi.lightBars(this);}
    boolean awaitLocal(long timeout)throws Exception{if(local.isShutdown()){if(!local.awaitTermination(timeout,TimeUnit.MILLISECONDS))return false;}else local.submit(()->{}).get(timeout,TimeUnit.MILLISECONDS);return folder.await(timeout);}
    @Override protected void onDestroy(){generation++;local.shutdown();if(!isChangingConfigurations())folder.close();main.removeCallbacksAndMessages(null);super.onDestroy();}
}
